<?php require_once __DIR__.'/includes/bootstrap.php';$pageTitle='Official Documents';$q=trim($_GET['q']??'');$type=trim($_GET['type']??'');$docs=rows($pdo,'SELECT * FROM documents WHERE (:t="" OR type=:t) AND (:q="" OR title LIKE :like) ORDER BY issued_date DESC',['t'=>$type,'q'=>$q,'like'=>'%'.$q.'%']);require __DIR__.'/includes/header.php';?><main><a class="back" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Explore information / Official Documents</a><section class="hero"><i class="fa-solid fa-file-lines"></i><div><h1>Official Documents</h1><p>Access public records, ordinances, and certificate requirements.</p></div></section><section class="section"><article class="panel"><form class="form-grid" method="get"><div><label for="q">Search documents</label><input id="q" name="q" value="<?= h($q) ?>"></div><div><label for="type">Document type</label><select id="type" name="type"><option value="">All types</option><?php foreach(['ordinance','resolution','form'] as $t):?><option value="<?= $t ?>" <?= $type===$t?'selected':'' ?>><?= ucfirst($t) ?></option><?php endforeach;?></select></div><div class="full"><button class="button">Filter documents</button></div></form></article></section><section class="section"><h2>Ordinances & resolutions</h2><div class="panel"><table><thead><tr><th>Type</th><th>Title</th><th>Date issued</th><th></th></tr></thead><tbody><?php $records=array_filter($docs,fn($d)=>in_array($d['type']??'', ['ordinance','resolution'],true));if(!$records):?><tr><td colspan="4" class="empty">No public documents have been published yet.</td></tr><?php else:foreach($records as $d):?><tr><td><?= h(ucfirst($d['type'])) ?></td><td><?= h($d['title']) ?><br><span class="meta"><?= h($d['description']??'') ?></span></td><td><?= h($d['issued_date']??'') ?></td><td><a class="button alt" href="download.php?id=<?= (int)$d['id'] ?>">Download</a></td></tr><?php endforeach;endif;?></tbody></table></div></section><section class="section"><h2>Downloadable forms</h2><div class="grid"><?php $forms=array_filter($docs,fn($d)=>($d['type']??'')==='form');if(!$forms):?><div class="panel empty">No forms have been published yet.</div><?php else:foreach($forms as $f):?><article class="panel"><h3><?= h($f['title']) ?></h3><p><?= h($f['description']??'') ?></p><a class="button alt" href="download.php?id=<?= (int)$f['id'] ?>">Download form</a></article><?php endforeach;endif;?></div></section><section class="section"><article class="panel"><h2>Request a service</h2><p>Request a certificate and receive a reference number for follow-up.</p><?php if(isset($_GET['reference'])):?><div class="success">Request submitted. Reference number: <strong><?= h($_GET['reference']) ?></strong>.</div><?php elseif(logged_in()):?><form method="post" action="request-certificate.php" class="form-grid"><input type="hidden" name="csrf_token" value="<?= csrf() ?>"><div><label>Certificate type</label><select name="cert_type" required><option>Barangay Clearance</option><option>Certificate of Residency</option><option>Certificate of Indigency</option></select></div><div><label>Purpose</label><input name="purpose" required></div><div class="full"><button class="button">Request certificate</button></div></form><?php else:?><button class="button" data-requires-login data-authenticated="0" data-intent="request a certificate">Request / apply</button><?php endif;?></article></section></main><?php require __DIR__.'/includes/login-gate-modal.php';require __DIR__.'/includes/footer.php';?>
